class Solution {
public:
    int uniqueMorseRepresentations(vector<string>& words) {
        vector<string> morse = {
            ".-","-...","-.-.","-..",".","..-.","--.","....","..",".---",
            "-.-",".-..","--","-.","---",".--.","--.-",".-.","...","-",
            "..-","...-",".--","-..-","-.--","--.."
        };
        unordered_set<string> seen;
        for (const string& w : words) {
            string t;
            for (char c : w) {
                t += morse[c - 'a'];
            }
            seen.insert(t);
        }
        return static_cast<int>(seen.size());
    }
};
